import re


def mots(texte):
    return re.findall(r"[a-zàâçéèêëîïôûùüÿœ]+", texte.lower())


def predire_suivant(table, mot):
    if mot not in table:
        return None
    options = table[mot]
    return max(options, key=options.get)


def generer(table, debut, n):
    phrase = [debut]
    for _ in range(n):
        suivant = predire_suivant(table, phrase[-1])
        if suivant is None:
            break
        phrase.append(suivant)
    return " ".join(phrase)


def suivants(texte):
    liste = mots(texte)
    table = {}
    for a, b in zip(liste, liste[1:]):
        table.setdefault(a, {})
        table[a][b] = table[a].get(b, 0) + 1
    return table


def ecrire(texte, debut, n):
    return generer(suivants(texte), debut, n)
